//! gRPC service for MCP Gateway
//!
//! Protobuf Rust code is generated by `build.rs` into `OUT_DIR` and included
//! below as `$OUT_DIR/proto/jarvis.mcp.gateway.v1.rs`. That generated file is
//! the single source of truth: the former checked-in `src/proto/` copy was
//! unused (no `mod` declaration referenced it) and byte-identical, so it was
//! removed. Do not reintroduce a checked-in generated file here.

use crate::McpGateway;
use jarvis_core::INTERNAL_GATEWAY_ERROR_MESSAGE as INTERNAL_ERROR_MESSAGE;
use tonic::{Request, Response, Status};

pub mod proto {
    include!(concat!(env!("OUT_DIR"), "/proto/jarvis.mcp.gateway.v1.rs"));
}

use proto::mcp_gateway_service_server::{McpGatewayService, McpGatewayServiceServer};
use proto::{Empty, ExecuteToolRequest, ExecuteToolResponse, RegisterMcpRequest};

/// Metadata header carrying the shared gRPC token.
const GRPC_TOKEN_HEADER: &str = "x-jarvis-grpc-token";

/// Log an internal failure server-side and return a sanitized `Status`.
///
/// The caller-visible message is the shared `INTERNAL_ERROR_MESSAGE` aliased
/// from `jarvis-core` above; internal causes (paths, tokens, upstream text)
/// stay in the server log because a gRPC status is observable by any caller.
fn sanitized_internal_status(detail: impl std::fmt::Display) -> Status {
    tracing::error!(error = %detail, "gRPC request failed with internal gateway error");
    Status::internal(INTERNAL_ERROR_MESSAGE)
}

/// Map a malformed `args` JSON error onto the fixed gRPC contract.
///
/// The `serde_json::Error` is deliberately never read: its `Display`/`Debug`
/// text carries caller-derived fragments, a byte offset and an expected-token
/// description. It is absorbed here and only a fixed `error_kind` (shared with
/// `jarvis_core`'s `BareJson` vocabulary) reaches tracing, so neither the
/// status nor OTLP/Grafana can echo the offending input (V-43).
fn invalid_args_json_status(_error: serde_json::Error) -> Status {
    tracing::debug!(
        error_kind = jarvis_core::INVALID_JSON_BODY_ERROR_KIND,
        field = "args",
        "invalid client input"
    );
    Status::invalid_argument(crate::http::safe_client_error_text(
        "invalid tool arguments",
    ))
}

/// Map a gateway error to a gRPC status by its concrete type.
///
/// This mirrors `http::http_status_for`: the status code is derived from
/// `McpGatewayError::kind()`, never from the human-readable message. The
/// caller-visible message likewise uses the same fixed vocabulary as the HTTP
/// adapter (`http::safe_client_error_text` for client errors and
/// `http::POLICY_DENIED_MESSAGE` for denials); echoing `error.to_string()`
/// leaked absolute sandbox paths, egress hosts and upstream names into a
/// status observable by any caller. Unknown error types fall back to
/// `Internal` and are sanitized like any other gateway-side failure.
fn grpc_status_for(error: &anyhow::Error) -> Status {
    use crate::error::ErrorKind;

    let kind = error
        .downcast_ref::<crate::error::McpGatewayError>()
        .map(crate::error::McpGatewayError::kind)
        .unwrap_or(ErrorKind::Internal);
    match kind {
        ErrorKind::ClientError => {
            let text = crate::http::safe_client_error_text(&error.to_string());
            Status::invalid_argument(text)
        }
        ErrorKind::Forbidden => Status::permission_denied(crate::http::POLICY_DENIED_MESSAGE),
        ErrorKind::Internal => sanitized_internal_status(error),
    }
}

pub struct GrpcMcpGatewayService {
    gateway: McpGateway,
    admin_token: Option<String>,
}

/// Fixed-size digest comparison for the gRPC token gate.
///
/// Both the presented and configured tokens are converted to `[u8; 32]`
/// SHA-256 digests and all 32 bytes are XOR-folded with no early exit. The
/// digest absorbs input length, so the loop is always exactly 32 iterations —
/// unlike the previous length-inclusive padded XOR loop, whose iteration count
/// depended on the input length. Mirrors
/// `jarvis_policy::kill_switch::constant_time_eq`; the digest primitive is
/// reused from that crate because this one has no direct `sha2` dependency.
/// No `unsafe` code is involved and neither token value is ever logged.
///
/// A missing or blank presented token is rejected without comparison. A blank
/// configured value is rejected too: startup validation forbids it, and this
/// is the request-time backstop for programmatically built configs.
fn token_matches(provided: Option<&str>, expected: &str) -> bool {
    // Blank expected values are never credentials (defense in depth).
    if expected.trim().is_empty() {
        return false;
    }
    provided.is_some_and(|p| {
        // A blank header/metadata value must not authenticate an empty
        // configured token through the digest comparison (R4-FIX a).
        if p.trim().is_empty() {
            return false;
        }
        fixed_size_digest_eq(p, expected)
    })
}

/// Compare two tokens via fixed-size SHA-256 digests.
///
/// Both operands are `[u8; 32]`, so the XOR fold visits exactly 32 bytes and
/// never branches on a mismatch or on the original token lengths.
fn fixed_size_digest_eq(a: &str, b: &str) -> bool {
    let a: [u8; 32] = jarvis_policy::kill_switch::sha256_digest(a);
    let b: [u8; 32] = jarvis_policy::kill_switch::sha256_digest(b);
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= *x ^ *y;
    }
    diff == 0
}

/// Authorize a gRPC call before any handler work runs.
///
/// `admin_only` marks management RPCs (currently `RegisterMcpServer`): they
/// must never run without a configured token. Data-plane RPCs only require
/// the token when one is configured, preserving legacy loopback callers.
fn authorize_grpc<T>(
    request: &Request<T>,
    expected: Option<&str>,
    admin_only: bool,
) -> Result<(), Status> {
    let provided = request
        .metadata()
        .get(GRPC_TOKEN_HEADER)
        .and_then(|v| v.to_str().ok());
    match expected {
        Some(token) if token_matches(provided, token) => Ok(()),
        Some(_) => Err(Status::unauthenticated("invalid or missing gRPC token")),
        None if admin_only => Err(Status::unauthenticated(
            "administrative gRPC RPCs require JARVIS_MCP_GW_ADMIN_TOKEN",
        )),
        None => Ok(()),
    }
}

#[tonic::async_trait]
impl McpGatewayService for GrpcMcpGatewayService {
    async fn execute_tool(
        &self,
        request: Request<ExecuteToolRequest>,
    ) -> Result<Response<ExecuteToolResponse>, Status> {
        authorize_grpc(&request, self.admin_token.as_deref(), false)?;
        let req = request.into_inner();
        let args: serde_json::Value =
            serde_json::from_str(&req.args).map_err(invalid_args_json_status)?;
        let result = self
            .gateway
            .execute_tool(&req.tool, args, &req.principal)
            .await
            .map_err(|e| grpc_status_for(&e))?;
        let result = serde_json::to_string(&result).map_err(sanitized_internal_status)?;
        Ok(Response::new(ExecuteToolResponse { result }))
    }

    async fn register_mcp_server(
        &self,
        request: Request<RegisterMcpRequest>,
    ) -> Result<Response<Empty>, Status> {
        authorize_grpc(&request, self.admin_token.as_deref(), true)?;
        let req = request.into_inner();
        self.gateway
            .register_mcp_server(&req.name, req.command)
            .await
            .map_err(|e| grpc_status_for(&e))?;
        Ok(Response::new(Empty {}))
    }
}

pub async fn serve(
    gateway: McpGateway,
    addr: std::net::SocketAddr,
    admin_token: Option<String>,
) -> anyhow::Result<()> {
    let service = GrpcMcpGatewayService {
        gateway,
        admin_token,
    };
    tonic::transport::Server::builder()
        .add_service(McpGatewayServiceServer::new(service))
        .serve(addr)
        .await?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use tonic::Code;

    /// Build a service backed by a real `McpGateway`. The gateway itself is
    /// never reached by the invalid-JSON test (deserialization fails first),
    /// but the handler requires a fully constructed instance.
    async fn test_service_with_token(
        label: &str,
        admin_token: Option<String>,
    ) -> GrpcMcpGatewayService {
        let dir = std::env::temp_dir().join(format!("jarvis-mcp-gw-grpc-{label}"));
        let _ = std::fs::remove_dir_all(&dir);
        tokio::fs::create_dir_all(&dir)
            .await
            .expect("create temp dir");
        let allowlist = dir.join("mcp_allowlist.toml");
        tokio::fs::write(
            &allowlist,
            r#"
principals = ["test"]

[[tools]]
name = "echo"
description = "Echo tool"
allowed_principals = ["test"]
max_args_size = 1048576
timeout_ms = 5000
requires_approval = false
"#,
        )
        .await
        .expect("write allowlist");
        let config = crate::config::McpGatewayConfig {
            allowlist_path: allowlist.to_string_lossy().into_owned(),
            ..Default::default()
        };
        let policy = crate::testing::shipped_policy_client(label).await;
        let gateway = crate::McpGateway::new(config, Arc::new(policy))
            .await
            .expect("gateway starts");
        GrpcMcpGatewayService {
            gateway,
            admin_token,
        }
    }

    async fn test_service(label: &str) -> GrpcMcpGatewayService {
        test_service_with_token(label, None).await
    }

    fn request_with_token<T>(payload: T, token: Option<&str>) -> Request<T> {
        let mut request = Request::new(payload);
        if let Some(token) = token {
            request.metadata_mut().insert(
                GRPC_TOKEN_HEADER,
                token.parse().expect("valid metadata token"),
            );
        }
        request
    }

    #[test]
    fn authorize_grpc_enforces_configured_token() {
        let request = request_with_token((), Some("correct-token"));
        assert!(authorize_grpc(&request, Some("correct-token"), false).is_ok());

        for provided in [None, Some("wrong-token")] {
            let request = request_with_token((), provided);
            let status = authorize_grpc(&request, Some("correct-token"), false)
                .expect_err("invalid or missing token must be rejected");
            assert_eq!(status.code(), Code::Unauthenticated);
        }
    }

    /// Blank metadata must never authenticate, not even when the configured
    /// token is blank. `load()` now rejects blank config at startup; this is
    /// the request-time backstop for programmatically built configs.
    #[test]
    fn authorize_grpc_rejects_blank_metadata_even_with_blank_config() {
        for blank in ["", " ", "   "] {
            let request = request_with_token((), Some(blank));
            let status = authorize_grpc(&request, Some(""), false)
                .expect_err("blank metadata must be rejected");
            assert_eq!(status.code(), Code::Unauthenticated);
        }

        let request = request_with_token((), Some("correct-token"));
        let status = authorize_grpc(&request, Some("   "), false)
            .expect_err("blank configured token must be rejected");
        assert_eq!(status.code(), Code::Unauthenticated);
    }

    /// `token_matches` now uses a fixed-size digest comparison that mirrors
    /// `kill_switch::constant_time_eq`: both operands become `[u8; 32]` and the
    /// XOR fold always visits 32 bytes, independent of token length. A
    /// shorter, a longer, and a same-length wrong token must all be rejected,
    /// as must blank values. An exact non-blank match still passes.
    #[test]
    fn token_matches_rejects_length_and_content_mismatches() {
        let expected = "correct-token";

        assert!(token_matches(Some(expected), expected));
        // R4-FIX (a): this used to assert success for empty/empty. A blank
        // presented token is never a credential, even when the configured
        // value is blank (which startup validation now rejects as well).
        assert!(!token_matches(Some(""), ""));
        assert!(!token_matches(Some("   "), "   "));

        // Same-length content mismatch.
        assert!(!token_matches(Some("Correct-token"), expected));

        // Length mismatches in both directions: length is now absorbed by the
        // digest, and the fixed-size XOR fold rejects them all the same.
        assert!(!token_matches(Some("correct"), expected));
        assert!(!token_matches(Some("correct-token-extra"), expected));

        // A prefix-only match must not be accepted by the digest comparison.
        assert!(!token_matches(Some("correct-to"), expected));

        // Missing token stays rejected (unchanged fail-closed contract).
        assert!(!token_matches(None, expected));

        // Long inputs: an exact match passes, while a one-byte extension that
        // changes only the tail is still rejected by the 32-byte digest fold.
        let long = "l".repeat(4096);
        assert!(token_matches(Some(long.as_str()), long.as_str()));
        let longer = format!("{long}x");
        assert!(!token_matches(Some(longer.as_str()), long.as_str()));
    }

    /// The call site rejects a length-mismatched header token with the same
    /// status as a same-length wrong one, and never echoes token values.
    #[test]
    fn authorize_grpc_rejects_length_mismatched_header_token() {
        for provided in [
            Some("correct"),
            Some("correct-token-extra"),
            Some("Correct-token"),
        ] {
            let request = request_with_token((), provided);
            let status = authorize_grpc(&request, Some("correct-token"), false)
                .expect_err("length/content mismatch must be rejected");
            assert_eq!(status.code(), Code::Unauthenticated);
            assert!(!status.message().contains("correct-token"));
            assert!(!status.message().contains(provided.unwrap_or("")));
        }
    }

    #[test]
    fn authorize_grpc_keeps_admin_rpc_fail_closed_without_token() {
        let request = request_with_token((), None);
        let status = authorize_grpc(&request, None, true)
            .expect_err("admin RPC must fail closed when no token is configured");
        assert_eq!(status.code(), Code::Unauthenticated);

        // Data-plane RPCs stay usable for legacy loopback callers.
        assert!(authorize_grpc(&request, None, false).is_ok());
    }

    #[tokio::test]
    async fn register_mcp_server_requires_admin_token() {
        let service = test_service("admin-no-token").await;
        let request = Request::new(RegisterMcpRequest {
            name: "probe".into(),
            command: vec!["/bin/true".into()],
        });
        let status = service
            .register_mcp_server(request)
            .await
            .expect_err("unauthenticated admin RPC must be rejected");
        assert_eq!(status.code(), Code::Unauthenticated);
    }

    #[tokio::test]
    async fn register_mcp_server_accepts_correct_admin_token() {
        let service =
            test_service_with_token("admin-with-token", Some("admin-secret".into())).await;
        let request = request_with_token(
            RegisterMcpRequest {
                name: "probe".into(),
                // Empty command is rejected by the gateway after authorization;
                // reaching that error proves the auth gate was passed.
                command: Vec::new(),
            },
            Some("admin-secret"),
        );
        let status = service
            .register_mcp_server(request)
            .await
            .expect_err("empty command is still rejected by the gateway");
        // An empty command is a typed `ClientError` (gateway.rs `client_error`),
        // so the shared contract maps it to InvalidArgument, not Internal. Its
        // text is already in the fixed vocabulary, so it passes through the
        // shared `safe_client_error_text` helper verbatim.
        assert_eq!(status.code(), Code::InvalidArgument);
        assert_eq!(status.message(), "MCP server command must not be empty");
    }

    /// Malformed `args` must be reported as `INVALID_ARGUMENT` instead of
    /// panicking (which, under `panic = "abort"`, would kill the whole gateway).
    #[tokio::test]
    async fn invalid_args_json_returns_invalid_argument_without_panicking() {
        let service = test_service("invalid-args").await;
        let request = Request::new(ExecuteToolRequest {
            tool: "echo".into(),
            args: "{ this is not valid json".into(),
            principal: "test".into(),
        });

        let status = service
            .execute_tool(request)
            .await
            .expect_err("malformed args JSON must be rejected");
        assert_eq!(status.code(), Code::InvalidArgument);
        assert_eq!(
            status.message(),
            crate::http::safe_client_error_text("invalid tool arguments")
        );
        for leaked in ["expected value", "line 1", "column", "invalid args JSON"] {
            assert!(!status.message().contains(leaked), "leaked '{leaked}'");
        }
    }

    /// V-43 regression: the raw serde error (derived from caller input) must
    /// be absorbed before tracing. Only the fixed `error_kind` and message are
    /// logged, so no offending fragment, offset or serde detail reaches
    /// OTLP/Grafana. A function-local static Mutex serializes the test because
    /// `tracing::subscriber::with_default` is thread-local, while the test
    /// harness runs tests in parallel on separate threads.
    #[test]
    fn invalid_args_json_never_logs_raw_error_detail() {
        static LOG_CAPTURE_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
        let _guard = LOG_CAPTURE_LOCK.lock().expect("log capture lock poisoned");

        #[derive(Clone, Default)]
        struct LogBuffer(std::sync::Arc<std::sync::Mutex<Vec<u8>>>);

        impl std::io::Write for LogBuffer {
            fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
                let mut guard = self.0.lock().expect("log buffer mutex");
                guard.extend_from_slice(buf);
                Ok(buf.len())
            }

            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }

        const PROBE: &str = "PROBE_MALFORMED_ARGS_INPUT";
        let malformed = format!("{{ {PROBE}}}");
        let raw_detail = serde_json::from_str::<serde_json::Value>(&malformed)
            .expect_err("probe is malformed")
            .to_string();

        let buffer = LogBuffer::default();
        let writer = buffer.clone();
        let subscriber = tracing_subscriber::fmt()
            .without_time()
            .with_target(false)
            .with_max_level(tracing::Level::DEBUG)
            .with_writer(move || writer.clone())
            .finish();

        let status = tracing::subscriber::with_default(subscriber, || {
            let error = serde_json::from_str::<serde_json::Value>(&malformed)
                .expect_err("probe is malformed");
            invalid_args_json_status(error)
        });

        assert_eq!(status.code(), Code::InvalidArgument);
        assert_eq!(
            status.message(),
            crate::http::safe_client_error_text("invalid tool arguments")
        );

        let captured = buffer.0.lock().expect("log buffer mutex").clone();
        let logs = String::from_utf8(captured).expect("logs are utf-8");
        assert!(
            logs.contains("invalid client input"),
            "fixed log is missing: {logs}"
        );
        assert!(!logs.contains(PROBE), "raw input leaked to logs: {logs}");
        assert!(
            !logs.contains(raw_detail.as_str()),
            "raw serde detail leaked: {logs}"
        );
        assert!(
            !logs.contains("error ="),
            "raw error field leaked to logs: {logs}"
        );
    }

    /// Every `ErrorKind` must map to its agreed gRPC code, and the caller-
    /// visible message must come from the fixed vocabulary shared with HTTP —
    /// never from the raw error text. Absolute sandbox paths, egress hosts and
    /// upstream server names are logged server-side only (Internal) or reduced
    /// to a static phrase by `http::safe_client_error_text` (ClientError).
    #[test]
    fn grpc_status_for_maps_error_kinds_and_hides_internal_detail() {
        use crate::error::{ErrorKind, McpGatewayError};

        let cases: [(anyhow::Error, ErrorKind, Code, &str); 12] = [
            (
                McpGatewayError::ArgsTooLarge {
                    tool: "echo".into(),
                    max: 4,
                    actual: 8,
                }
                .into(),
                ErrorKind::ClientError,
                Code::InvalidArgument,
                "invalid tool arguments",
            ),
            (
                McpGatewayError::ClientError("missing url".into()).into(),
                ErrorKind::ClientError,
                Code::InvalidArgument,
                "invalid tool arguments",
            ),
            (
                McpGatewayError::ClientError(
                    "read /home/koppe/secret-project/token.txt: permission denied".into(),
                )
                .into(),
                ErrorKind::ClientError,
                Code::InvalidArgument,
                "invalid tool arguments",
            ),
            (
                McpGatewayError::ClientError(
                    "host 'attacker.example' is not in the egress allowlist".into(),
                )
                .into(),
                ErrorKind::ClientError,
                Code::InvalidArgument,
                "host is not allowed by the egress policy",
            ),
            (
                McpGatewayError::ClientError(
                    "MCP server 'upstream.internal.example:8443' is unreachable".into(),
                )
                .into(),
                ErrorKind::ClientError,
                Code::InvalidArgument,
                "upstream MCP server is unavailable",
            ),
            (
                McpGatewayError::NotAllowed("echo".into()).into(),
                ErrorKind::Forbidden,
                Code::PermissionDenied,
                crate::http::POLICY_DENIED_MESSAGE,
            ),
            (
                McpGatewayError::PolicyDenied {
                    tool: "echo".into(),
                    principal: "test".into(),
                }
                .into(),
                ErrorKind::Forbidden,
                Code::PermissionDenied,
                crate::http::POLICY_DENIED_MESSAGE,
            ),
            (
                McpGatewayError::PrincipalNotAllowed {
                    principal: "test".into(),
                    tool: "echo".into(),
                }
                .into(),
                ErrorKind::Forbidden,
                Code::PermissionDenied,
                crate::http::POLICY_DENIED_MESSAGE,
            ),
            (
                McpGatewayError::ApprovalRequired {
                    tool: "echo".into(),
                }
                .into(),
                ErrorKind::Forbidden,
                Code::PermissionDenied,
                crate::http::POLICY_DENIED_MESSAGE,
            ),
            (
                McpGatewayError::ApprovalDenied {
                    tool: "echo".into(),
                    reason: "no".into(),
                }
                .into(),
                ErrorKind::Forbidden,
                Code::PermissionDenied,
                crate::http::POLICY_DENIED_MESSAGE,
            ),
            (
                McpGatewayError::Sandbox("secret path /tmp/x".into()).into(),
                ErrorKind::Internal,
                Code::Internal,
                INTERNAL_ERROR_MESSAGE,
            ),
            // Untyped errors (including bare `anyhow!` values) fall back to
            // Internal, exactly as they do on the HTTP adapter.
            (
                anyhow::anyhow!("untyped secret detail"),
                ErrorKind::Internal,
                Code::Internal,
                INTERNAL_ERROR_MESSAGE,
            ),
        ];

        for (error, expected_kind, expected_code, expected_message) in cases {
            let actual_kind = error
                .downcast_ref::<McpGatewayError>()
                .map(McpGatewayError::kind)
                .unwrap_or(ErrorKind::Internal);
            assert_eq!(actual_kind, expected_kind);

            let status = grpc_status_for(&error);
            assert_eq!(status.code(), expected_code, "{error}");
            assert_eq!(status.message(), expected_message, "{error}");

            // Fixed vocabulary only: paths, hosts, upstream names and the raw
            // detail must never reach the caller-visible status message.
            let message = status.message();
            for leaked in [
                "/tmp",
                "/home/koppe",
                "secret",
                "attacker.example",
                "upstream.internal.example",
                "'echo'",
                "'test'",
            ] {
                assert!(!message.contains(leaked), "leaked '{leaked}' in {message}");
            }
        }
    }

    /// HTTP/gRPC joint status-contract regression (I25-B): the same typed
    /// gateway failure must surface as the agreed HTTP status and gRPC code
    /// on both adapters, and internal detail must stay out of gRPC statuses.
    #[tokio::test]
    async fn http_and_grpc_status_contracts_agree() {
        let dir = std::env::temp_dir().join("jarvis-mcp-gw-grpc-joint-status");
        let _ = std::fs::remove_dir_all(&dir);
        tokio::fs::create_dir_all(&dir)
            .await
            .expect("create temp dir");
        let allowlist = dir.join("mcp_allowlist.toml");
        tokio::fs::write(
            &allowlist,
            r#"
principals = ["opencode"]

[[tools]]
name = "shell.execute"
description = "Echo tool"
allowed_principals = ["opencode"]
max_args_size = 8
timeout_ms = 5000
requires_approval = false

[[tools]]
name = "filesystem.read"
description = "Read tool"
allowed_principals = ["opencode"]
max_args_size = 1048576
timeout_ms = 5000
requires_approval = false
"#,
        )
        .await
        .expect("write allowlist");
        let config = crate::config::McpGatewayConfig {
            allowlist_path: allowlist.to_string_lossy().into_owned(),
            ..Default::default()
        };
        let policy = crate::testing::shipped_policy_client("joint-status").await;
        let gateway = crate::McpGateway::new(config, Arc::new(policy))
            .await
            .expect("gateway starts");

        // A mock upstream returning an MCP error result: `gateway.execute`
        // turns that into an untyped internal failure (anyhow::bail!).
        let (client_side, server_side) = tokio::io::duplex(8192);
        tokio::spawn(crate::testing::run_mock_mcp_server(
            server_side,
            "filesystem.read",
            true,
        ));
        gateway
            .register_transport("mock", client_side)
            .await
            .expect("mock registers");

        // Real HTTP router on an ephemeral port, backed by the same gateway.
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind http test server");
        let base = format!("http://{}", listener.local_addr().expect("http addr"));
        let app = crate::http::router(Arc::new(gateway.clone()));
        tokio::spawn(async move {
            axum::serve(listener, app).await.expect("http server runs");
        });
        let http = reqwest::Client::new();

        let service = GrpcMcpGatewayService {
            gateway,
            admin_token: None,
        };

        // ClientError: oversized arguments -> 400 / InvalidArgument.
        let big_args = serde_json::json!({ "cmd": "a".repeat(64) });
        let http_status = http
            .post(format!("{base}/v1/execute"))
            .json(&serde_json::json!({
                "tool": "shell.execute",
                "args": big_args.clone(),
                "principal": "opencode",
            }))
            .send()
            .await
            .expect("http execute runs")
            .status();
        let grpc_status = service
            .execute_tool(Request::new(ExecuteToolRequest {
                tool: "shell.execute".into(),
                args: big_args.to_string(),
                principal: "opencode".into(),
            }))
            .await
            .expect_err("oversized args rejected by grpc");
        assert_eq!(http_status, reqwest::StatusCode::BAD_REQUEST);
        assert_eq!(grpc_status.code(), Code::InvalidArgument);
        assert_eq!(grpc_status.message(), "invalid tool arguments");
        assert!(!grpc_status.message().contains("exceed"));

        // Forbidden: principal denied by policy -> 403 / PermissionDenied.
        let http_status = http
            .post(format!("{base}/v1/execute"))
            .json(&serde_json::json!({
                "tool": "filesystem.read",
                "args": { "path": "/tmp/example" },
                "principal": "test",
            }))
            .send()
            .await
            .expect("http execute runs")
            .status();
        let grpc_status = service
            .execute_tool(Request::new(ExecuteToolRequest {
                tool: "filesystem.read".into(),
                args: r#"{"path":"/tmp/example"}"#.into(),
                principal: "test".into(),
            }))
            .await
            .expect_err("policy-denied principal rejected by grpc");
        assert_eq!(http_status, reqwest::StatusCode::FORBIDDEN);
        assert_eq!(grpc_status.code(), Code::PermissionDenied);
        assert_eq!(grpc_status.message(), crate::http::POLICY_DENIED_MESSAGE);
        assert!(!grpc_status.message().contains("Policy denied"));
        assert!(!grpc_status.message().contains("filesystem.read"));
        assert!(!grpc_status.message().contains("'test'"));

        // Internal: upstream MCP error result -> 500 / Internal, with the
        // detailed cause logged server-side and replaced by a fixed message.
        let http_status = http
            .post(format!("{base}/v1/execute"))
            .json(&serde_json::json!({
                "tool": "filesystem.read",
                "args": { "path": "/tmp/example" },
                "principal": "opencode",
            }))
            .send()
            .await
            .expect("http execute runs")
            .status();
        let grpc_status = service
            .execute_tool(Request::new(ExecuteToolRequest {
                tool: "filesystem.read".into(),
                args: r#"{"path":"/tmp/example"}"#.into(),
                principal: "opencode".into(),
            }))
            .await
            .expect_err("upstream MCP error rejected by grpc");
        assert_eq!(http_status, reqwest::StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(grpc_status.code(), Code::Internal);
        assert_eq!(grpc_status.message(), INTERNAL_ERROR_MESSAGE);
        assert!(!grpc_status.message().contains("returned an error"));
    }

    /// Build a service with a tiny argument cap so a generic client-input
    /// failure can be exercised over HTTP and gRPC alike. Uses the same
    /// shipped-policy principal/tool pair as the joint-status regression.
    async fn test_service_with_args_cap(
        label: &str,
        max_args_size: usize,
    ) -> GrpcMcpGatewayService {
        let dir = std::env::temp_dir().join(format!("jarvis-mcp-gw-grpc-{label}"));
        let _ = std::fs::remove_dir_all(&dir);
        tokio::fs::create_dir_all(&dir)
            .await
            .expect("create temp dir");
        let allowlist = dir.join("mcp_allowlist.toml");
        tokio::fs::write(
            &allowlist,
            format!(
                r#"
principals = ["opencode"]

[[tools]]
name = "shell.execute"
description = "Echo tool"
allowed_principals = ["opencode"]
max_args_size = {max_args_size}
timeout_ms = 5000
requires_approval = false
"#
            ),
        )
        .await
        .expect("write allowlist");
        let config = crate::config::McpGatewayConfig {
            allowlist_path: allowlist.to_string_lossy().into_owned(),
            ..Default::default()
        };
        let policy = crate::testing::shipped_policy_client(label).await;
        let gateway = crate::McpGateway::new(config, Arc::new(policy))
            .await
            .expect("gateway starts");
        GrpcMcpGatewayService {
            gateway,
            admin_token: None,
        }
    }

    /// Cross-transport vocabulary regression (I83-C a): malformed JSON must
    /// never leak serde_json detail on either adapter. HTTP collapses a broken
    /// body to a bare 400 (`BareJson`); gRPC reduces a malformed `args` string
    /// to the very same fixed client-error token the HTTP adapter puts in its
    /// 400 body. The raw error is left to the server log only.
    #[tokio::test]
    async fn malformed_json_uses_same_fixed_vocabulary_on_http_and_grpc() {
        let service = test_service_with_args_cap("json-vocab", 8).await;
        let app = crate::http::router(Arc::new(service.gateway.clone()));
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind http test server");
        let base = format!("http://{}", listener.local_addr().expect("http addr"));
        tokio::spawn(async move {
            axum::serve(listener, app).await.expect("http server runs");
        });
        let http = reqwest::Client::new();

        // HTTP client-error bucket: oversized args -> 400 with fixed body.
        let oversized = serde_json::json!({ "cmd": "a".repeat(64) });
        let response = http
            .post(format!("{base}/v1/execute"))
            .json(&serde_json::json!({
                "tool": "shell.execute",
                "args": oversized,
                "principal": "opencode",
            }))
            .send()
            .await
            .expect("http execute runs");
        assert_eq!(response.status(), reqwest::StatusCode::BAD_REQUEST);
        let body: serde_json::Value = response.json().await.expect("http error body is JSON");
        let http_message = body["error"]
            .as_str()
            .expect("400 body carries an error token");

        // HTTP syntax error: bare 400, no serde detail in the response.
        let syntax = http
            .post(format!("{base}/v1/execute"))
            .header("content-type", "application/json")
            .body("{ this is not valid json")
            .send()
            .await
            .expect("http syntax request runs");
        assert_eq!(syntax.status(), reqwest::StatusCode::BAD_REQUEST);
        let syntax_body = syntax.text().await.expect("http syntax body");
        assert!(
            !syntax_body.contains("expected value"),
            "serde detail leaked: {syntax_body}"
        );

        // gRPC: the malformed `args` string must produce the very same token
        // as the HTTP client-error body, with no serde_json detail attached.
        let status = service
            .execute_tool(Request::new(ExecuteToolRequest {
                tool: "shell.execute".into(),
                args: "{ this is not valid json".into(),
                principal: "opencode".into(),
            }))
            .await
            .expect_err("malformed args rejected by grpc");
        assert_eq!(status.code(), Code::InvalidArgument);
        assert_eq!(
            status.message(),
            crate::http::safe_client_error_text("invalid tool arguments")
        );
        assert_eq!(
            status.message(),
            http_message,
            "HTTP/gRPC vocabulary diverged"
        );
        for leaked in ["expected value", "line 1", "column", "invalid args JSON"] {
            assert!(!status.message().contains(leaked), "leaked '{leaked}'");
        }
    }
}
